        ggml_backend_t backends[GGML_CUDA_MAX_DEVICES];
        void *         data[GGML_CUDA_MAX_DEVICES];
        bool           compute[GGML_CUDA_MAX_DEVICES];
        ggml_type      type;
        bool           use_bf16;
        int64_t
